@startuml

class City {
  + Name : string
  + NumberOfInhabitants : int
}

class Attraction {
  + Name : string
  + Address : string
}

class GuidedTour {
  + Duration : int
  + Number : int
}

class Discount {
  + Amount : int
}

class Person {
  + Name : string
}

class Visitor extends Person {}

class Guide extends Person {}

City "1" -- "*" Attraction
Attraction "1" -- "*" GuidedTour
GuidedTour "*" -- "1" Guide
GuidedTour "1" -- "0..20" Visitor
Visitor "0..1" -- "0..1" Discount
Discount "*" -- "1" GuidedTour

@enduml

